// Scenario forecast; rates must be supplied or learned separately from history.
export function allocate(lots,drivers,coordinated=true){if(!Number.isInteger(drivers)||drivers<0||drivers>200)throw Error('Число водителей: 0–200');const forecast=lots.map(p=>{for(const k of ['free','capacity','arrivals','departures','drive','walk'])if(!Number.isFinite(p[k])||p[k]<0)throw Error('Параметры должны быть неотрицательными числами');if(p.free>p.capacity)throw Error('Свободных мест больше вместимости');return Math.floor(Math.max(0,Math.min(p.capacity,p.free+(p.departures-p.arrivals)*p.drive)));});const assigned=lots.map(()=>0);let unassigned=0;for(let i=0;i<drivers;i++){const candidates=lots.map((p,j)=>({j,score:p.drive+p.walk})).filter(({j})=>lots[j].walk<=5&&(!coordinated||assigned[j]<forecast[j])).sort((a,b)=>a.score-b.score||a.j-b.j);if(!candidates.length){unassigned++;continue;}assigned[candidates[0].j]++;}const overflow=assigned.reduce((s,n,i)=>s+Math.max(0,n-forecast[i]),0);return{forecast,assigned,overflow,unassigned};}
export function initAllocation(){const $=id=>document.getElementById(id);let cv=null;document.addEventListener('oqim-parking-cv',e=>{cv=e.detail;$('allocationCV').disabled=false;$('allocationSource').textContent=`Получено из видео: ${cv.free} свободных из ${cv.capacity} размеченных мест. Нажмите «Использовать CV для А».`;});$('allocationCV').onclick=()=>{if(!cv)return;$('allocFree0').value=cv.free;$('allocCapacity0').value=cv.capacity;$('allocationSource').textContent='А: наблюдение из загруженного видео (не live). Темпы въезда/выезда и время поездки остаются гипотезами.';run();};function run(){try{const lots=[0,1,2].map(i=>Object.fromEntries(['free','capacity','arrivals','departures','drive','walk'].map(k=>[k,+$(`alloc${k[0].toUpperCase()+k.slice(1)}${i}`).value]))),drivers=+$('allocDrivers').value,base=allocate(lots,drivers,false),smart=allocate(lots,drivers,true);$('allocationResult').textContent=`Одинаковый спрос: ${drivers} водителей. Прогноз свободных к прибытию А / Б / В: ${smart.forecast.join(' / ')}. Ближайшая: направлено ${base.assigned.join(' / ')}, сверх прогноза ${base.overflow}. OQIM: направлено ${smart.assigned.join(' / ')}, сверх прогноза ${smart.overflow}, без подходящего места ${smart.unassigned}.`;}catch(e){$('allocationResult').textContent=e.message;}}$('allocationRun').onclick=run;run();}
